 */
public int compareAndUpdateStatus(String batchKey, String status, long expectedVersion) {
    return jdbc.update(
            "UPDATE batch SET status = ?, version = version + 1 WHERE batch_key = ? AND version = ?",
            status, batchKey, expectedVersion);
}

