        // 10^12 秒下降 2*10^11 千帕：速率恰 0.2/秒；长整数时刻差与大压力值必须精确
        PressureCurveEvaluator.Evaluation e = PressureCurveEvaluator.evaluate(
                points(0L, "200000000000.000", 1_000_000_000_000L, "0.000"));
